insert into public.site_content (key, data) values
  ('general', '{"name":"Panji Prakorso","tagline":"Marketing | Digital | Performance | Growth","role":"Marketing Professional"}'::jsonb),
  ('hero', '{"eyebrow":"Marketing Professional","headingLines":[{"text":"Marketing","accent":false},{"text":"Digital","accent":false},{"text":"Performance","accent":true},{"text":"Growth","accent":true}],"description":"Marketing professional building brands, driving customer acquisition, and turning digital strategy into measurable business impact.","primaryCtaLabel":"View selected work","primaryCtaHref":"#projects","secondaryCtaLabel":"Get in touch","secondaryCtaHref":"#contact","image":"/assets/portrait.svg","imageAlt":"Panji Prakorso, marketing professional","badge":"Brand · Digital · Performance · Growth"}'::jsonb),
  ('stats', '{"items":[{"value":"8+","label":"Years Professional Experience"},{"value":"3","label":"Featured Projects"},{"value":"4","label":"Marketing Disciplines"}]}'::jsonb),
  ('about', '{"label":"About me","heading":"Marketing at the intersection of","headingAccent":"Brand, Digital, Performance & Growth.","description":"Combining marketing strategy, digital execution, performance marketing and customer acquisition to build measurable growth.","note":"Eight years across consumer technology, marketplace and entrepreneurial businesses — the through-line is the same: understand the customer, build the funnel, and prove the impact with data.","image":"","cvLabel":"Download CV","cvUrl":"/assets/panji-prakorso-cv.pdf"}'::jsonb),
  ('disciplines', '{"items":[{"number":"01","title":"Brand","description":"","icon":"brand","items":["Consumer insight","Brand strategy","Content","Creator marketing"]},{"number":"02","title":"Digital","description":"","icon":"digital","items":["Digital strategy","Website","SEO","Social media"]},{"number":"03","title":"Performance","description":"","icon":"performance","items":["Paid media","Customer acquisition","Lead generation","Optimization"]},{"number":"04","title":"Growth","description":"","icon":"growth","items":["Funnel strategy","Analytics","ROI","Growth strategy"]}]}'::jsonb),
  ('projectsSection', '{"label":"Featured Projects","title":"Selected Work","lead":"Three businesses. Three different challenges. One marketing mindset."}'::jsonb),
  ('impact', '{"label":"Selected Historical Impact","title":"Impact That Matters","items":[{"value":"4X","label":"YoY Sales Growth"},{"value":"+727%","label":"Total Users"},{"value":"-77%","label":"CPC"},{"value":"+276%","label":"CTR"},{"value":"13.24X","label":"Website Engaged Sessions"}],"attribution":"Axioo Indonesia","note":"Selected historical impact achieved at Axioo Indonesia. These describe past performance in that role and period, not current 2026 results."}'::jsonb),
  ('milestones', '{"label":"Experience","title":"Career Milestones","lead":"Eight years of compounding scope — from commercial foundation to manager-level marketing across brand, digital, performance and growth.","items":[{"year":"2018","title":"Professional Foundation","description":"Commercial and marketing fundamentals — understanding customers, products and how a business actually makes money."},{"year":"2022","title":"Digital Marketing Transition","description":"Moved into digital: owned channels, website, content and analytics as the core of the marketing mix."},{"year":"2023","title":"Digital & Performance Marketing","description":"Combined digital execution with paid media and measurement — campaigns judged on acquisition, not activity."},{"year":"2025","title":"Performance Marketing Leadership","description":"Leading acquisition quality, campaign efficiency and full-funnel optimisation at marketplace scale."},{"year":"2026","title":"Manager-Level Growth","description":"Operating across brand, digital, performance and growth — building marketing systems that compound."}]}'::jsonb),
  ('framework', '{"label":"How I think","title":"A four-step way of working,","titleAccent":"applied to every brief.","lead":"Strategy before channel, execution before opinion, data before the next budget. The same loop runs whether the goal is brand, acquisition or efficiency.","items":[{"number":"01","title":"Understand","caption":"Start with the business, not the channel.","items":["Business","Customer","Market"]},{"number":"02","title":"Strategize","caption":"Decide where to play before deciding how to spend.","items":["Positioning","Audience","Channel","Funnel"]},{"number":"03","title":"Execute","caption":"Ship the work — consistently, across the whole funnel.","items":["Campaign","Content","Digital","Performance"]},{"number":"04","title":"Optimize","caption":"Let the data decide what earns the next budget.","items":["Data","Testing","Efficiency","Growth"]}]}'::jsonb),
  ('tools', '{"label":"Tools & Technologies","title":"What I work with","groups":[{"group":"Performance & Analytics","tools":["Google Ads","Meta Ads","Google Analytics","Looker Studio","SEO"]},{"group":"Technical","tools":["HTML / CSS","JavaScript","Python","SQL"]},{"group":"Workflow","tools":["Airtable","Figma","WordPress"]}]}'::jsonb),
  ('contact', '{"label":"Contact","title":"Let''s build","titleAccent":"what''s next.","lead":"Open to Marketing, Digital, Performance and Growth opportunities.","ctaLabel":"Get in touch","email":"panji.prakorso@gmail.com","phone":"","location":"Jakarta, Indonesia","linkedinLabel":"linkedin.com/in/panjiprakorso","linkedinUrl":"https://www.linkedin.com/in/panjiprakorso/","instagramLabel":"@panjiprakorso","instagramUrl":"https://www.instagram.com/panjiprakorso/"}'::jsonb)
insert into public.projects (slug, position, featured, data) values
  ('99-group', 0, true, '{"number":"01","title":"99 Group","displayTitle":"99 GROUP","category":"Performance / Growth / Customer Acquisition","categoryShort":"Performance / Growth","disciplines":["Performance","Growth","Customer Acquisition"],"shortDescription":"Improving acquisition quality, campaign efficiency and customer growth.","heroDescription":"Moving the acquisition conversation from volume to quality — tightening audiences, targeting and campaign optimisation so every lead that enters the funnel is worth working.","visual":"dashboard","tags":["Paid Media","Lead Quality","Funnel Optimisation","Analytics"],"cardMetrics":[{"value":"-30%+","label":"Spam Rate"},{"value":"+20%","label":"Qualified Lead Conversion"},{"value":"15–25%","label":"CPL Efficiency"}],"chapters":[{"id":"context","label":"Context","title":"A high-volume acquisition engine with a quality problem","body":["99 Group operates at property-marketplace scale, where paid media runs continuously across multiple markets and lead volume is never the constraint.","My focus sat on the demand side of that engine: the campaigns, audiences and funnel steps that decide not just how many leads arrive, but how many of them a sales team can actually work."]},{"id":"challenge","label":"Challenge","title":"Acquisition volume does not always translate into acquisition quality","body":["Campaigns optimised purely for lead volume were pulling in a growing share of spam and low-intent submissions. That inflated reported performance while quietly increasing cost per usable lead and eroding trust in the numbers downstream."],"bullets":["Lead volume looked healthy while qualified conversion lagged behind","Spam and low-intent form fills consumed sales capacity","Cost per lead was optimised in isolation from lead quality","Channel performance was hard to compare without a shared quality signal"]},{"id":"strategy","label":"Strategy","title":"Optimise for qualified demand, not raw submissions","body":["The strategy re-anchored every optimisation decision to a quality-weighted definition of success, then worked backwards into audience, targeting and creative."],"columns":[{"title":"Audience Strategy","items":["Intent-led audience segmentation","Separating prospecting from retargeting economics","Prioritising segments with proven downstream conversion"]},{"title":"Targeting","items":["Tighter geo, placement and device targeting","Exclusions built from historic low-quality sources","Message-to-audience matching by funnel stage"]},{"title":"Campaign Optimisation","items":["Bidding and budget shifted toward qualified outcomes","Structured creative and landing-page testing","Continuous pruning of underperforming placements"]},{"title":"Quality Control","items":["Form and validation hardening against spam","Lead-quality feedback loop back into campaigns","Shared quality reporting across channels"]}]},{"id":"execution","label":"Execution","title":"A repeatable optimisation loop","body":["Execution ran as a weekly cycle rather than a one-off fix: read the quality signal, act on the campaign, measure the downstream effect, then reset the baseline."],"bullets":["Rebuilt campaign structure around quality-weighted objectives","Applied validation and filtering to reduce spam at the point of capture","Fed qualified-lead outcomes back into bidding and audience decisions","Ran structured tests on creative, copy and landing experience","Reported on cost per qualified lead alongside cost per lead"]}],"impact":{"label":"Measured Impact","attribution":"99 Group — performance & growth marketing","note":"Results reflect the acquisition-quality programme described above, measured against the pre-optimisation baseline.","items":[{"value":"-30%+","label":"Spam Rate"},{"value":"+20%","label":"Qualified Lead Conversion"},{"value":"15–25%","label":"CPL Efficiency"}]},"learning":"Efficiency and quality are the same problem viewed from two ends. Once qualified conversion became the metric campaigns were judged on, cost per lead improved as a by-product — not the other way around."}'::jsonb),
  ('perkasa-motors', 1, true, '{"number":"02","title":"Perkasa Motors","displayTitle":"PERKASA MOTORS","category":"Business Building / Marketing / Automotive","categoryShort":"Business / Marketing","disciplines":["Business Building","Brand","Digital Ecosystem","Marketing"],"shortDescription":"Building a modern automotive business and digital ecosystem from the ground up.","heroDescription":"An entrepreneurial marketing project: designing the brand, the business model and the digital ecosystem of an automotive business from a blank page.","visual":"automotive","tags":["Business Building","Brand","Digital Ecosystem","Marketing"],"cardMetrics":[],"chapters":[{"id":"business-context","label":"Business Context","title":"Starting an automotive business from zero","body":["Perkasa Motors is a used-car business built from the ground up — not a marketing brief handed over by a client, but a company where positioning, operations and demand generation had to be designed together.","That makes it the clearest test of marketing thinking I have: no existing brand equity, no inherited traffic, no legacy funnel. Every decision had to earn its place commercially."]},{"id":"brand","label":"Brand","title":"A trust-first identity in a low-trust category","body":["Used-car buying is a high-consideration, trust-sensitive purchase. The brand was built to answer that directly: clear presentation, honest vehicle information and a consistent identity across every surface a buyer touches."],"bullets":["Positioning built around transparency and buyer confidence","Consistent visual identity across digital and physical touchpoints","Vehicle presentation standards treated as brand, not admin","Tone of voice that informs rather than pressures"]},{"id":"business-model","label":"Business Model","title":"Marketing decisions tied to unit economics","body":["Inventory, pricing and demand generation are one system. Marketing here is not a layer on top of the business — it sets which vehicles get sourced, how they are priced and how quickly they need to move."],"bullets":["Inventory selection informed by observed demand signals","Pricing and presentation aligned to buyer expectations","Enquiry handling designed as part of the funnel, not after it","Marketing effort weighted toward stock that needs velocity"]},{"id":"digital-ecosystem","label":"Digital Ecosystem","title":"Owned platform first, channels second","body":["The digital ecosystem was built so the business owns its shopfront rather than renting attention entirely from marketplaces and social platforms."],"bullets":["Website as the canonical inventory and brand destination","Structured listing pages built for search discoverability","Direct enquiry routes into conversation, not into a form void","Social profiles positioned as top-of-funnel discovery","Analytics and tracking in place from day one"]},{"id":"marketing","label":"Marketing","title":"Full-funnel execution at small-business scale","body":["With a founder-scale budget, the marketing model prioritises compounding assets — content, listings and search presence — supported by targeted paid activity rather than the reverse."],"bullets":["Content and vehicle storytelling as the primary demand asset","Search and marketplace visibility for high-intent buyers","Social content for reach, credibility and remarketing pools","Paid media used selectively against specific inventory goals"]}],"impact":{"label":"Current Progress","attribution":"Perkasa Motors — ongoing","note":"Perkasa Motors is an active, early-stage business. No performance metrics are published here, because none have been independently verified yet. The evidence below is qualitative and deliberately kept that way.","items":[],"qualitative":["Brand identity, positioning and presentation standards defined and in use","Owned website and inventory experience live as the primary digital asset","Digital ecosystem — website, listings, social and analytics — operating together","Marketing model running end to end, from discovery through to enquiry handling","Ongoing build: results will be reported once measured over a meaningful period"]},"learning":"Owning the business changes how you weigh marketing decisions. When the cost of a bad channel choice is your own inventory sitting still, you stop optimising for activity and start optimising for what actually moves stock."}'::jsonb),
  ('axioo-pongo', 2, true, '{"number":"03","title":"Axioo / Pongo","displayTitle":"AXIOO / PONGO","category":"Brand / Digital / Performance","categoryShort":"Brand / Digital / Performance","disciplines":["Brand","Digital","Performance"],"shortDescription":"Building digital presence, customer engagement and measurable growth across Axioo and Pongo.","heroDescription":"Brand, digital and performance working as one system across a technology manufacturer and its gaming line — from digital presence through to full-funnel acquisition.","visual":"devices","tags":["Brand","Digital Presence","Full-Funnel","Creator Marketing"],"cardMetrics":[{"value":"4X","label":"YoY Sales Growth"},{"value":"+727%","label":"Total Users"},{"value":"-77%","label":"CPC"}],"chapters":[{"id":"brand-context","label":"Brand Context","title":"A local technology brand and its gaming line","body":["Axioo is an Indonesian technology and laptop brand; Pongo is its gaming-focused line. The two share infrastructure but speak to different audiences — one broad and value-led, the other enthusiast, community-driven and highly comparison-oriented.","The work spanned both: a single digital and performance operating model, with brand expression and messaging tuned per audience."]},{"id":"digital-ecosystem","label":"Digital Ecosystem","title":"Presence built to convert, not just to exist","body":["The digital estate was treated as a growth asset: the website, product pages and campaign destinations all measured on their contribution to engaged sessions and conversion, not on traffic alone."],"bullets":["Website and product experience as the centre of the ecosystem","Campaign landing experiences aligned to ad message and audience","Analytics, event tracking and dashboarding for shared visibility","SEO and content supporting non-paid discovery"]},{"id":"full-funnel","label":"Full-Funnel Marketing","title":"One funnel, three jobs","body":["Rather than running awareness and performance as separate budgets, activity was planned as a single funnel with distinct jobs at each stage and a clear hand-off between them."],"columns":[{"title":"Awareness","items":["Brand and product storytelling","Creator and community reach","Broad-audience video and social"]},{"title":"Consideration","items":["Comparison and spec-led content","Retargeting from engaged audiences","Review and community proof"]},{"title":"Conversion","items":["High-intent search and shopping","Offer and launch campaigns","Marketplace and retail alignment"]}]},{"id":"performance","label":"Performance Marketing","title":"Efficiency earned through structure and testing","body":["Performance gains came from campaign architecture and disciplined iteration rather than from spending more: cleaner audience separation, sharper creative-to-intent matching and continuous pruning of what did not earn its budget."],"bullets":["Campaign restructure around audience intent and funnel stage","Systematic creative testing on hooks, formats and messaging","Bid, budget and placement optimisation against efficiency targets","Landing-page and post-click experience improvements","Measurement framework connecting spend to engaged sessions and sales"]},{"id":"creators","label":"Creator Partnerships","title":"Community credibility as a growth channel","body":["In gaming and technology, third-party credibility outperforms brand claims. Creator partnerships were used to build genuine product proof, then that content was recycled into paid placements where it consistently outperformed studio-made assets."],"bullets":["Creator selection based on audience fit over follower count","Product-led briefs that allowed honest, native treatment","Creator content repurposed into paid social and retargeting","Community engagement sustained beyond campaign windows"]}],"impact":{"label":"Selected Historical Impact","attribution":"Axioo Indonesia","note":"These are selected historical results achieved during my time at Axioo Indonesia. They describe past performance in that role and period — not current 2026 results, and not a projection of future outcomes.","items":[{"value":"4X","label":"YoY Sales Growth"},{"value":"+727%","label":"Total Users"},{"value":"-77%","label":"CPC"},{"value":"+276%","label":"CTR"},{"value":"13.24X","label":"Website Engaged Sessions"}]},"learning":"Brand and performance are not competing budgets. The cheapest clicks came from the work that built credibility first — creator proof and a stronger brand made every performance campaign that followed more efficient."}'::jsonb)
